import {renderTurf} from './turf-ui.js';
const voteLabel=n=>n+' '+(n%10===1&&n%100!==11?'голос':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'голоси':'голосів');
export const MODES={trivia:{name:'Вікторина',icon:'✳',description:'1–8 гравців · 10 запитань · одному або з друзями'},imposter:{name:'Імпостер',icon:'◉',description:'3–8 гравців із телефонами · секретне слово · блеф і голосування'},duel:{name:'Битва за поле',icon:'▦',description:'2 гравці · спільне поле · вікторина · п’ять у ряд'},millionaire:{name:'Мільйонер',icon:'◇',description:'1 гравець · 15 запитань · 50:50'}};
export function modePicker(mode,esc){return `<div class="party-modes">${Object.entries(MODES).map(([id,m])=>`<button type="button" id="mode-${id}" data-new-mode="${id}" class="${mode===id?'chosen':''}" aria-pressed="${mode===id}"><span>${m.icon}</span><strong>${m.name}</strong><small>${m.description}</small></button>`).join('')}</div>`;}
export function renderParty(s,{host,esc,btn,players,playerDot,roleVisible}){
 if(!s||s.phase==='lobby'||s.phase==='closed')return null;if(s.mode==='duel'&&s.duel?.version===2)return renderTurf(s,{host,esc,btn,players,playerDot});
 const me=s.players.find(p=>p.id===s.you),title=MODES[s.mode]?.name;
 const meta=`<div class="game-top"><span class="eyebrow">${title} · ${s.code}</span><strong id="timer" class="timer" role="timer"></strong></div>`;
 const close=host?btn('close','Завершити гру','secondary'):'';
 if(s.mode==='imposter'){
  const g=s.imposter,ordered=g.turnOrder.map(id=>s.players.find(p=>p.id===id));
  const secret=!host&&s.secret?`<div class="secret-card"><span class="eyebrow">ЛИШЕ ДЛЯ ВАС</span>${roleVisible?`<h2>${s.secret.role==='imposter'?'Ви — імпостер':esc(s.secret.word)}</h2><p>${s.secret.role==='imposter'?'Ви не знаєте слова. Слухайте підказки та спробуйте не видати себе.':'Дайте підказку одним словом. Не називайте саме секретне слово.'}</p>`:'<h2>Ваша таємна картка</h2><p>Переконайтеся, що ніхто не бачить ваш екран.</p>'}${btn('secret',roleVisible?'Сховати картку':'Показати мою картку','secondary')}</div>`:'';
  if(s.phase==='finished')return `<section class="party-summary">${meta}<div class="orb">${g.winner==='group'?'✓':'◉'}</div><h1>${g.winner==='group'?'Група перемогла!':'Імпостер переміг!'}</h1><p>Слово: <strong>${esc(g.word)}</strong></p><p>Імпостер: <strong>${esc(s.players.find(p=>p.id===g.imposterId)?.name)}</strong></p><p>${g.guess?`Спроба імпостера: «${esc(g.guess)}» — ${g.guessedCorrect?'влучно':'неправильно'}.`:g.accusedId?`Група обрала: ${esc(s.players.find(p=>p.id===g.accusedId)?.name)}.`:'Однозначного вибору немає — імпостер уникнув викриття.'}</p><div class="players">${s.players.map((p,i)=>`<div class="player">${playerDot(p,i)}<strong>${esc(p.name)}</strong><small>${voteLabel(Object.values(g.votes).filter(id=>id===p.id).length)}${p.id===g.imposterId?' · імпостер':''}</small></div>`).join('')}</div><div class="actions">${host?btn('again','Ще один раунд →'):btn('leave','До входу','secondary')}${close}</div></section>`;
  if(s.phase==='roles')return `<section class="party-stage">${meta}<h1>Тримайте слово в таємниці.</h1>${host?'<p>Кожен відкриває картку на своєму телефоні та натискає «Готово». На TV ролі не показуються.</p>':secret}${me?(g.ready.includes(me.id)?'<p class="feedback">Ви готові. Чекаємо на решту…</p>':`<div class="actions">${btn('ready','Картку переглянуто · готово ✓','primary',!roleVisible)}</div>`):''}<div class="players">${s.players.map((p,i)=>`<div class="player">${playerDot(p,i)}<strong>${esc(p.name)}</strong><small>${g.ready.includes(p.id)?'✓ Готовий':'Дивиться картку'}</small></div>`).join('')}</div><div class="actions">${close}</div></section>`;
  const voted=g.voted.includes(me?.id);
  return `<section class="party-stage">${meta}<h1>${s.phase==='discussion'?'Одне слово. Багато підозр.':'Хто з вас імпостер?'}</h1>${s.phase==='discussion'?`<p>Говоріть по черзі за списком. Кожен дає одну підказку, пов’язану зі словом. Потім обговоріть підозри.</p><div class="turn-order">${ordered.map((p,i)=>`<div class="player">${playerDot(p,s.players.indexOf(p))}<strong>${i+1}. ${esc(p.name)}</strong></div>`).join('')}</div>`:`<p>${g.voted.length} із ${s.players.length} проголосували. Результати відкриються після всіх голосів або завершення хвилини.</p>${!host&&!voted?`<div class="vote-options">${s.players.filter(p=>p.id!==me?.id).map(p=>`<button id="vote-${p.id}" data-vote="${p.id}" ${s.paused?'disabled':''}>${playerDot(p,s.players.indexOf(p))}${esc(p.name)}</button>`).join('')}</div>`:!host?'<p class="feedback">Голос прийнято. Чекаємо на інших…</p>':''}`}${secret}${!host&&s.secret?.role==='imposter'?`<form id="guess" class="guess-form"><label for="guess-word">Здогадалися? Одна спроба одразу завершує раунд.</label><input id="guess-word" name="word" maxlength="40" placeholder="Секретне слово" required ${s.paused?'disabled':''}><button class="secondary" ${s.paused?'disabled':''}>Назвати слово</button></form>`:''}<div class="actions">${host&&s.phase==='discussion'?btn('voting','До голосування →'):''}${host?btn(s.paused?'resume':'pause',s.paused?'Продовжити ▶':'Пауза Ⅱ','secondary'):''}${close}</div><p class="status"></p></section>`;
 }
 if(s.mode==='duel'){
  if(s.phase==='question')return null;
  const board=(p,i)=>{const b=s.duel.boards[p.id],enabled=s.phase==='claim'&&!s.paused&&p.id===s.you;return `<article class="duel-board" style="--territory-color:${p.color}"><h2>${playerDot(p,i)} ${esc(p.name)}</h2><div class="board-direction">СТАРТ → → → → ФІНІШ</div><div class="tile-grid">${b.map((owned,tile)=>`<button id="tile-${p.id}-${tile}" data-tile="${tile}" class="tile ${owned?'owned':''} ${enabled&&s.duel.claimable.includes(tile)?'available':''}" ${!enabled||!s.duel.claimable.includes(tile)?'disabled':''} aria-label="${esc(p.name)}: ряд ${Math.floor(tile/5)+1}, стовпчик ${tile%5+1}${owned?', ваша територія':''}">${owned?'●':enabled&&s.duel.claimable.includes(tile)?'+':''}</button>`).join('')}</div></article>`;};
  const finished=s.phase==='finished',winners=s.duel.winners;
  return `<section class="duel-stage">${meta}<h1>${finished?(winners.length===2?'Нічия!':esc(s.players.find(p=>p.id===winners[0])?.name)+' перемагає!'):s.phase==='claim'?'Правильно? Розширюйте територію.':'Наступний крок до перемоги.'}</h1>${!finished?`<p>Правильна відповідь: <strong>${esc(s.question.choices[s.question.correct])}</strong>. ${s.phase==='claim'?(s.duel.pending.includes(me?.id)?'Оберіть підсвічену клітинку на своєму полі.':'Чекаємо, поки гравці оберуть клітинки. Через 20 секунд — автоматичний вибір.'):'Результат раунду зафіксовано.'}</p>`:'<p>Перемога — з’єднати лівий і правий краї свого поля. Після 20 раундів без шляху перемагає гравець із більшою кількістю правильних відповідей.</p>'}<div class="duel-boards">${s.players.map(board).join('')}</div><div class="actions">${host?(finished?btn('new','Нова кімната →'):s.phase==='reveal'?btn('next','Наступний раунд →'):btn(s.paused?'resume':'pause',s.paused?'Продовжити ▶':'Пауза Ⅱ','secondary')):''}${finished&&!host?btn('leave','До входу','secondary'):''}${close}</div><p class="status"></p></section>`;
 }
 return null;
}
